class Solution {
public:
    int maxAbsoluteSum(vector<int>& nums) {
        int prefix = 0;
        int max_p = 0;
        int min_p = 0;
        for (int x : nums) {
            prefix += x;
            if (prefix > max_p) max_p = prefix;
            if (prefix < min_p) min_p = prefix;
        }
        return max_p - min_p;
    }
};

