var maxAbsoluteSum = function(nums) {
    let prefix = 0;
    let max_p = 0;
    let min_p = 0;
    for (const x of nums) {
        prefix += x;
        if (prefix > max_p) max_p = prefix;
        if (prefix < min_p) min_p = prefix;
    }
    return max_p - min_p;
};
